const CHUNK_SIZE = $("Configuration").first().json.chunk_size;

const item = items[0];

// Get the file uploaded by the Form Trigger
// (the field is named "file" → binary.file; fallback to the first binary found)
const bin =
  item.binary?.file ||
  (item.binary ? item.binary[Object.keys(item.binary)[0]] : null);

if (!bin?.data) {
  throw new Error('No file received. Make sure the field is named "file".');
}

const override =
  item.json?.fields?.fileNameOverride?.toString().trim() ||
  item.json?.fileNameOverride?.toString().trim() ||
  '';

const fileName = override || bin.fileName || 'upload.bin';
const mimeType = bin.mimeType || 'application/octet-stream';

const buf = Buffer.from(bin.data, 'base64');
const totalChunks = Math.max(1, Math.ceil(buf.length / CHUNK_SIZE));

const out = [];
for (let i = 0; i < totalChunks; i++) {
  const start = i * CHUNK_SIZE;
  const end = Math.min(start + CHUNK_SIZE, buf.length);
  const slice = buf.subarray(start, end);

  out.push({
    json: {
      fileName,
      chunkNumber: i,       // 0-based like the UI
      totalChunks,
      size: slice.length
    },
    binary: {
      chunk: {
        data: slice.toString('base64'),
        fileName,
        mimeType
      }
    }
  });
}

return out;
"},"typeVersion":2},{"id":"fc76d2f5-8ea6-4d8e-bf64-7772d1735860","name":"Upload Chunk","type":"n8n-nodes-base.httpRequest","position":[-960,688],"parameters":{"url":"={{ $('Configuration').item.json.fileflows_url }}/api/library-file/upload","method":"POST","options":{},"sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"name":"fileName","value":"={{$json["fileName"]}}"},{"name":"chunkNumber","value":"={{$json["chunkNumber"]}}"},{"name":"totalChunks","value":"={{$json["totalChunks"]}}"},{"name":"file","parameterType":"formBinaryData","inputDataFieldName":"chunk"}]}},"typeVersion":4.2},{"id":"d0277bd8-7c34-4220-9005-4f1aa00c2409","name":"Result","type":"n8n-nodes-base.noOp","position":[-1184,384],"parameters":{},"typeVersion":1},{"id":"646cd48f-d686-4d8a-a477-f892c2bfbf4d","name":"If succeed","type":"n8n-nodes-base.if","position":[-736,384],"parameters":{"options":{},"conditions":{"options":{"version":2,"leftValue":"","caseSensitive":true,"typeValidation":"strict"},"combinator":"and","conditions":[{"id":"7cb6c8ab-074b-4ccf-a1e1-cc0163c9090d","operator":{"type":"string","operation":"exists","singleValue":true},"leftValue":"={{ $json.data }}","rightValue":""}]}},"typeVersion":2.2},{"id":"9c135f4b-a927-4ed0-97c0-7e634be06668","name":"Split audio file","type":"n8n-nodes-base.httpRequest","position":[-512,240],"parameters":{"url":"={{ $('Configuration').item.json.fileflows_url }}/api/library-file/manually-add","method":"POST","options":{},"jsonBody":"={
