const jobs = $input.all();
const daysThreshold = $('Set Configuration').first().json.daysToCheck || 7;
const now = new Date();
const thresholdDate = new Date(now.getTime() - (daysThreshold * 24 * 60 * 60 * 1000));

// Helper function to parse relative dates
function parseDaysAgo(dateString) {
  if (!dateString) return new Date();

  const daysAgoMatch = dateString.match(/(\d+)\s*days?\s*ago/i);
  if (daysAgoMatch) {
    return new Date(now.getTime() - (parseInt(daysAgoMatch[1]) * 24 * 60 * 60 * 1000));
  }

  const hoursAgoMatch = dateString.match(/(\d+)\s*hours?\s*ago/i);
  if (hoursAgoMatch) {
    return new Date(now.getTime() - (parseInt(hoursAgoMatch[1]) * 60 * 60 * 1000));
  }

  if (dateString.toLowerCase().includes('today') || dateString.toLowerCase().includes('just posted')) {
    return new Date();
  }
  if (dateString.toLowerCase().includes('yesterday')) {
    return new Date(now.getTime() - (24 * 60 * 60 * 1000));
  }

  const parsedDate = new Date(dateString);
  return !isNaN(parsedDate.getTime()) ? parsedDate : new Date();
}

// Deduplicate by jobId
const seen = new Set();
const uniqueJobs = [];

for (const job of jobs) {
  const jobId = job.json.jobId;
  if (!seen.has(jobId)) {
    seen.add(jobId);

    // Check if job is within threshold
    const jobDate = parseDaysAgo(job.json.postedAt);
    if (jobDate >= thresholdDate) {
      uniqueJobs.push(job);
    }
  }
}

return uniqueJobs;"},"typeVersion":2},{"id":"16d6a4ab-7c49-42cc-96e6-6bfda5d05db1","name":"Google Sheets - Save Raw Jobs","type":"n8n-nodes-base.googleSheets","position":[784,336],"parameters":{"options":{},"sheetName":{"__rl":true,"mode":"name","value":"Raw Jobs"},"documentId":{"__rl":true,"mode":"id","value":"={{ $vars.GOOGLE_SHEETS_ID }}"}},"typeVersion":4.7},{"id":"cd3e473b-6c31-4166-8b7c-be4ea212ac80","name":"Code - Filter by Target Keywords","type":"n8n-nodes-base.code","position":[1008,336],"parameters":{"jsCode":"// Filter jobs by target keywords and add matched keyword info
const jobs = $input.all();
const filteredJobs = [];

for (const job of jobs) {
  const targetKeywords = (job.json.targetKeywords || '').split(',').map(k => k.trim().toLowerCase()).filter(k => k);
  const combinedText = (job.json.title + ' ' + job.json.description).toLowerCase();

  let matchedKeyword = null;
  for (const keyword of targetKeywords) {
    if (combinedText.includes(keyword)) {
      matchedKeyword = keyword;
      break;
    }
  }

  if (matchedKeyword) {
    filteredJobs.push({
      json: {
        ...job.json,
        matchedKeyword: matchedKeyword
      }
    });
  }
}

return filteredJobs.length > 0 ? filteredJobs : [{ json: { noMatches: true } }];"},"typeVersion":2},{"id":"3aa7482e-6806-4fab-b940-670ba3f375af","name":"IF - Check Matches Found","type":"n8n-nodes-base.if","position":[1232,336],"parameters":{"options":{},"conditions":{"options":{"leftValue":"","caseSensitive":false,"typeValidation":"loose"},"combinator":"and","conditions":[{"id":"cond-1","operator":{"type":"boolean","operation":"notTrue"},"leftValue":"={{ $json.noMatches }}"}]}},"typeVersion":2.2},{"id":"d2fd3e5d-7962-4127-8d09-b761852461ef","name":"Google Sheets - Save Qualified Leads","type":"n8n-nodes-base.googleSheets","position":[1728,320],"parameters":{"options":{},"sheetName":{"__rl":true,"mode":"name","value":"Qualified Leads"},"documentId":{"__rl":true,"mode":"id","value":"={{ $vars.GOOGLE_SHEETS_ID }}"}},"typeVersion":4.7},{"id":"124c8b65-6c67-43f7-ae44-bf92d9bbf6b6","name":"Schedule Trigger - Weekly Monday 8AM","type":"n8n-nodes-base.scheduleTrigger","position":[-784,688],"parameters":{"rule":{"interval":[{"field":"weeks","triggerAtDay":[1],"triggerAtHour":8}]}},"typeVersion":1.2},{"id":"98d382d0-3b75-4c36-8a21-1bf16694f880","name":"Set - Weekly Report Config","type":"n8n-nodes-base.set","position":[-560,688],"parameters":{"options":{},"assignments":{"assignments":[{"id":"week-config-1","name":"reportWeekStart","type":"string","value":"={{ $now.minus({days: 7}).format('yyyy-MM-dd') }}"},{"id":"week-config-2","name":"reportWeekEnd","type":"string","value":"={{ $now.format('yyyy-MM-dd') }}"}]},"includeOtherFields":true},"typeVersion":3.4},{"id":"33a4fe1b-d6e0-4789-ab7e-6ae34cb0e1e8","name":"Google Sheets - Get Raw Jobs (Weekly)","type":"n8n-nodes-base.googleSheets","position":[-336,592],"parameters":{"options":{},"sheetName":{"__rl":true,"mode":"name","value":"Raw Jobs"},"documentId":{"__rl":true,"mode":"id","value":"={{ $vars.GOOGLE_SHEETS_ID }}"}},"typeVersion":4.7},{"id":"b424e08f-47b0-46d1-98b3-0c4a67558a1d","name":"Google Sheets - Get Qualified Leads (Weekly)","type":"n8n-nodes-base.googleSheets","position":[-336,768],"parameters":{"options":{},"sheetName":{"__rl":true,"mode":"name","value":"Qualified Leads"},"documentId":{"__rl":true,"mode":"id","value":"={{ $vars.GOOGLE_SHEETS_ID }}"}},"typeVersion":4.7},{"id":"6ba80098-c778-45ce-bd9a-7289aa92a462","name":"Merge - Weekly Data","type":"n8n-nodes-base.merge","position":[-112,688],"parameters":{"mode":"combine","options":{},"combineBy":"combineAll"},"typeVersion":3},{"id":"91dc2eaa-aee1-4cf9-8cf4-784c40ab52b0","name":"Code - Aggregate Weekly Statistics","type":"n8n-nodes-base.code","position":[112,688],"parameters":{"jsCode":"// Aggregate weekly statistics
const rawJobs = $('Google Sheets - Get Raw Jobs (Weekly)').all();
const qualifiedLeads = $('Google Sheets - Get Qualified Leads (Weekly)').all();
const weekStart = $('Set - Weekly Report Config').first().json.reportWeekStart;
const weekEnd = $('Set - Weekly Report Config').first().json.reportWeekEnd;

// Filter to this week's data
const thisWeekJobs = rawJobs.filter(job => {
  const jobDate = job.json.scrapedDate;
  return jobDate >= weekStart && jobDate <= weekEnd;
});

const thisWeekLeads = qualifiedLeads.filter(lead => {
  const leadDate = lead.json.scrapedDate || lead.json.date;
  return leadDate >= weekStart && leadDate <= weekEnd;
});

// Calculate statistics
const stats = {
  totalJobs: thisWeekJobs.length,
  totalQualifiedLeads: thisWeekLeads.length,
  conversionRate: thisWeekJobs.length > 0 ? ((thisWeekLeads.length / thisWeekJobs.length) * 100).toFixed(1) : 0,
  bySource: {},
  byKeyword: {},
  topCompanies: {},
  highUrgency: 0,
  mediumUrgency: 0,
  lowUrgency: 0,
  avgUrgency: 0
};

// Count by source
for (const job of thisWeekJobs) {
