ersion":3.4},{"id":"1290ae98-0e18-4fcb-a25a-b1d0b12a09ae","name":"AI Agent","type":"@n8n/n8n-nodes-langchain.agent","position":[-624,-1184],"parameters":{"text":"=USER MESSAGE:
