const response = input;
const lat = $input.first().json.restaurantLat;
const lng = $input.first().json.restaurantLng;
const maxDistance = $input.first().json.maxServingDistance;

// Check if address was found
if (response.status !== "OK" || !response.results || response.results.length === 0) {
  return [{
    json: {
      valid: false,
      error: "Address not found",
      message: "Could not find that address. Please provide more details."
    }
  }];
}

const result = response.results[0];
const location = result.geometry.location;

// Restaurant location (replace with your actual coordinates)
const RESTAURANT_LAT = lat;  // Kyiv center example
const RESTAURANT_LNG = lng;

// Calculate distance using Haversine formula
function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

const distance = calculateDistance(
  RESTAURANT_LAT,
  RESTAURANT_LNG,
  location.lat,
  location.lng
);

// Delivery range limit (e.g., 5km)
const MAX_DELIVERY_DISTANCE = maxDistance;
const withinRange = distance <= MAX_DELIVERY_DISTANCE;

return [{
  json: {
    valid: true,
    withinRange: withinRange,
    formattedAddress: result.formatted_address,
    distance: Math.round(distance * 10) / 10, // Round to 1 decimal
    coordinates: {
      lat: location.lat,
      lng: location.lng
    },
    message: withinRange 
      ? `Address confirmed: ${result.formatted_address} (${Math.round(distance * 10) / 10}km away)`
      : `Sorry, ${result.formatted_address} is ${Math.round(distance * 10) / 10}km away. We only deliver within ${MAX_DELIVERY_DISTANCE}km.`
  }
}];"},"typeVersion":2},{"id":"e910c99d-fe9e-496c-8c9f-ec33fe06e1fc","name":"Set Location and Area","type":"n8n-nodes-base.set","position":[1936,32],"parameters":{"options":{},"assignments":{"assignments":[{"id":"4c8601b1-4228-4f52-89b3-55781e492172","name":"restaurantLat","type":"number","value":50.4504},{"id":"2cd58ef0-b796-4e3c-a4b9-bf2389bafe2f","name":"restaurantLng","type":"number","value":30.5245},{"id":"7d2ea368-73c7-4320-8ad7-5cac381ce156","name":"maxServingDistance","type":"number","value":100}]}},"typeVersion":3.4},{"id":"7a072a8c-f26c-4e76-900b-32665ab3329a","name":"Message1","type":"n8n-nodes-base.set","position":[2352,32],"parameters":{"options":{},"assignments":{"assignments":[{"id":"07fb056d-c9d5-45e2-9028-20c2560dce36","name":"Message","type":"string","value":"={{ $json.message }}"}]}},"typeVersion":3.4},{"id":"dcdcd1cd-7960-4024-8ebc-dd2ed9ff5556","name":"Trigger Node7","type":"n8n-nodes-base.set","position":[1504,32],"parameters":{"options":{},"assignments":{"assignments":[{"id":"57d0ec72-f5c1-40cd-bc08-7b3f85ba68eb","name":"address","type":"array","value":"string"}]}},"typeVersion":3.4},{"id":"46b1c608-ef56-445c-94db-08d79381b227","name":"Create a Delivery Order","type":"n8n-nodes-base.airtable","position":[1104,1168],"parameters":{"base":{"__rl":true,"mode":"list","value":"appO25aREhJMGVavR","cachedResultUrl":"https://airtable.com/appO25aREhJMGVavR","cachedResultName":"Restaurant Booking"},"table":{"__rl":true,"mode":"list","value":"tblcyTLCqeUGYeFY5","cachedResultUrl":"https://airtable.com/appO25aREhJMGVavR/tblcyTLCqeUGYeFY5","cachedResultName":"Orders"},"columns":{"value":{"Name":"={{ $json.name }}","Items":"={{ JSON.stringify($json.items) }}","Notes":"={{ $json.notes }}","Phone":"={{ $json.phone }}","Total":"={{ $json.priceTotal }}","Status":"🟡 Confirming","Order ID":"={{ $json.orderId }}","Order Type":"Delivery","Delivery Address":"={{ $json.deliveryAddress }}","Pickup/Delivery Time":"={{ $json.deliveryTime }}"},"schema":[{"id":"Order ID","ty