{"nodes":[{"id":"42fd2f04-7d83-44c9-a41b-48860efbcf79","name":"Jina AI DeepSearch Request","type":"n8n-nodes-base.httpRequest","position":[220,0],"parameters":{"url":"https://deepsearch.jina.ai/v1/chat/completions","method":"POST","options":{},"jsonBody":"={
