        <param name="Platform">{{ $('1. Get Next Post Idea from Sheet').item.json.Platform }} </param>
    </input_context>

    <output_instructions>
        Your response MUST be a single, valid JSON object containing exactly one key: `Caption`.
        The value of `Caption` MUST be a string containing the generated caption text, including hashtags.
        Example: `{"Caption": "Caption text tailored for LinkedIn goes here. #ProfessionalDevelopment #IndustryInsights"}`
        Do NOT include any other text, explanations, or formatting outside the JSON structure.
    </output_instructions>
</prompt>"}]},"promptType":"define","hasOutputParser":true},"typeVersion":1.5},{"id":"d4667681-a5aa-4b63-802c-2adf8c111bb9","name":"(LLM Model for Caption)","type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","position":[1560,-220],"parameters":{"options":{},"modelName":"models/gemini-2.0-flash"},"credentials":{"googlePalmApi":{"id":"hAoasnlx3jlRA3Kf","name":"BCP Gemini"}},"typeVersion":1},{"id":"59da1f6c-ee55-4095-8c95-d60d1177c142","name":"(Parse Caption JSON)","type":"@n8n/n8n-nodes-langchain.outputParserStructured","position":[1700,-220],"parameters":{"jsonSchemaExample":"{
