"},"typeVersion":3.4},{"id":"46c712d0-8e65-4da0-bdbc-9eadf4213f2f","name":"Fetch Stock Data","type":"n8n-nodes-base.httpRequest","position":[1020,0],"parameters":{"url":"=https://data.alpaca.markets/v2/stocks/bars","options":{},"sendQuery":true,"authentication":"genericCredentialType","genericAuthType":"httpCustomAuth","queryParameters":{"parameters":[{"name":"symbols","value":"={{ $json.symbols }}"},{"name":"timeframe","value":"1Day"},{"name":"limit","value":"1000"},{"name":"feed","value":"iex"},{"name":"=start","value":"={{ new Date(Date.now() - 100 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] }}"},{"name":"end","value":"={{ new Date().toISOString().split('T')[0] }}"}]}},"credentials":{"httpCustomAuth":{"id":"credential-id","name":"httpCustomAuth Credential"}},"typeVersion":4.2},{"id":"e8d96c0c-e927-4676-a02f-7729c0126165","name":"Interpret Data","type":"n8n-nodes-base.code","position":[1240,0],"parameters":{"language":"python","pythonCode":"import pandas as pd
import numpy as np
import json

bars_by_symbol = items[0]['json']['bars']
stocks = []

for symbol, bars in bars_by_symbol.items():
    closes = [bar['c'] for bar in bars if 'c' in bar]
    if len(closes) < 30:
        continue

    df = pd.DataFrame({'close': closes})

    # RSI(14)
    delta = df['close'].diff()
    gain = delta.clip(lower=0)
    loss = -delta.clip(upper=0)
    avg_gain = gain.rolling(14).mean()
    avg_loss = loss.rolling(14).mean()
    rs = avg_gain / avg_loss
    df['rsi'] = 100 - (100 / (1 + rs))

    # MACD (12,26,9)
    ema12 = df['close'].ewm(span=12, adjust=False).mean()
    ema26 = df['close'].ewm(span=26, adjust=False).mean()
    df['macd'] = ema12 - ema26
    df['signal'] = df['macd'].ewm(span=9, adjust=False).mean()

    latest = df.iloc[-1]
    rsi = latest['rsi']
    macd = latest['macd']
    signal = latest['signal']

    status = "Hold"
    if rsi < 30 and macd > signal:
        status = "Buy"
    elif rsi > 70 and macd < signal:
        status = "Sell"

    stocks.append({
        "ticker": symbol,
        "rsi": round(float(rsi), 2),
        "macd": round(float(macd), 2),
        "signal": round(float(signal), 2),
        "status": status
    })

return [{
    "json": {
        "summary": json.dumps({
            "stocks": stocks
        }, separators=(',', ':')),
      "stocks": stocks
    }
}]
"},"typeVersion":2},{"id":"5ace21ee-80b0-4d79-be68-ded17b53b5a2","name":"Stock Analysis Assistant","type":"@n8n/n8n-nodes-langchain.openAi","position":[1440,0],"parameters":{"text":"=Here is the technical indicator data as JSON:

