"type":"n8n-nodes-base.code","position":[960,680],"parameters":{"jsCode":"// Accessing data from the previous nodes
const openPositions = $('Alpaca_get_open_positions').all();
const topSentiment = $("filter_top_sentiment_score").all();

// Extracting the symbols for easier comparison
const openPositionSymbols = openPositions.map(pos => pos.json.symbol);
const topSentimentSymbols = topSentiment.map(sen => sen.json.stock);

// Table 1: Open positions not in the top sentiment filter
const positionsNotInTopSentiment = openPositions
  .filter(pos => !topSentimentSymbols.includes(pos.json.symbol))
  .map(pos => ({
    symbol: pos.json.symbol,
    market_value: pos.json.market_value,
    qty: pos.json.qty,
    asset_id : pos.json.asset_id
  }));

// Table 2: Symbols from top sentiment not in open positions
const symbolsNotInOpenPositions = topSentiment
  .filter(sen => !openPositionSymbols.includes(sen.json.stock))
  .map(sen => ({
    symbol: sen.json.stock,
  }));

// Calculate the total market value of the first table
const totalMarketValue = positionsNotInTopSentiment.reduce((sum, pos) => {
  return sum + parseFloat(pos.market_value);
}, 0);

// Calculate the value to be assigned to each symbol in the second table
const valuePerSymbol = symbolsNotInOpenPositions.length > 0
  ? totalMarketValue / symbolsNotInOpenPositions.length
  : 0;

// Add the calculated value to each symbol in the second table
const symbolsWithMarketValue = symbolsNotInOpenPositions.map(item => ({
  ...item,
  market_value_per_symbol: valuePerSymbol,
}));

// Returning the two tables as separate outputs
return [
  {
    json: {
      positions_not_in_top_sentiment: positionsNotInTopSentiment,

    symbols_not_in_open_positions: symbolsWithMarketValue,

  }}
];"},"typeVersion":2},{"id":"1e846978-377d-477f-9e62-5ae465066315","name":"positions_to_open","type":"n8n-nodes-base.splitOut","position":[1180,780],"parameters":{"options":{},"fieldToSplitOut":"symbols_not_in_open_positions"},"typeVersion":1},{"id":"a8bbdca1-d531-4384-bde9-8c1bf0979677","name":"positions_to_close","type":"n8n-nodes-base.splitOut","position":[1400,580],"parameters":{"options":{},"fieldToSplitOut":"positions_not_in_top_sentiment"},"typeVersion":1},{"id":"a6175bb8-d92e-4c36-9f70-9411567f80c8","name":"merge_orders_to_write_to_sheets","type":"n8n-nodes-base.merge","position":[1840,680],"parameters":{},"typeVersion":3.2},{"id":"61a3c87f-00f1-4dad-94c1-bd9ef1a9c906","name":"Google Sheets","type":"n8n-nodes-base.googleSheets","position":[2060,680],"parameters":{"columns":{"value":{"date":"={{ $today }}","order":"={{ $json.side }}","value":"={{ $if( $json.side == "buy",$json.notional,$('positions_to_close').item.json.market_value) }}","symbol":"={{ $json.symbol }}"},"schema":[{"id":"date","type":"string","display":true,"removed":false,"required":false,"displayName":"date","defaultMatch":false,"canBeUsedToMatch":true},{"id":"symbol","type":"string","display":true,"required":false,"displayName":"symbol","defaultMatch":false,"canBeUsedToMatch":true},{"id":"order","type":"string","display":true,"required":false,"displayName":"order","defaultMatch":false,"canBeUsedToMatch":true},{"id":"value","type":"string","display":true,"removed":false,"required":false,"displayName":"value","defaultMatch":false,"canBeUsedToMatch":true}],"mappingMode":"defineBelow","matchingColumns":["date"],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{},"operation":"append","sheetName":{"__rl":true,"mode":"list","value":486231870,"cachedResultUrl":"https://docs.google.com/spreadsheets/d/1tQDBVDqn5v08GOsjupjV8o3Jzqd4-fKoSoGhWLEOTww/edit#gid=486231870","cachedResultName":"positions"},"documentId":{"__rl":true,"mode":"list","value":"1tQDBVDqn5v08GOsjupjV8o3Jzqd4-fKoSoG