{"nodes":[{"id":"1","name":"CV Submission Webhook","type":"n8n-nodes-base.webhook","position":[240,300],"parameters":{"path":"cv-received","options":{},"httpMethod":"POST"},"typeVersion":1},{"id":"3","name":"Job Requirements","type":"n8n-nodes-base.set","position":[440,300],"parameters":{"values":{"number":[{"name":"minExperience","value":5},{"name":"passingScore","value":75}],"string":[{"name":"requiredSkills","value":"JavaScript,React,Node.js,Python"}]}},"typeVersion":1},{"id":"4","name":"Parse CV with AI","type":"n8n-nodes-base.httpRequest","position":[640,300],"parameters":{"url":"https://api.openai.com/v1/chat/completions","body":{"model":"gpt-4","messages":[{"role":"system","content":"You are a CV parsing expert. Extract key information from CVs and return structured JSON data."},{"role":"user","content":"Parse this CV and extract: name, email, phone, skills, experience_years, education, previous_roles. CV content: {{ $json.cv_content }}"}],"response_format":{"type":"json_object"}},"method":"POST","headers":{"Content-Type":"application/json","Authorization":"Bearer {{ $credentials.openai.apiKey }}"}},"typeVersion":1},{"id":"5","name":"Score Candidate","type":"n8n-nodes-base.code","position":[840,300],"parameters":{"jsCode":"// Intelligent candidate scoring algorithm
const candidate = $json.choices[0].message.content;
const requirements = $node['Job Requirements'].json;
const candidateData = JSON.parse(candidate);

let totalScore = 0;

// Skills matching (40% weight)
const requiredSkills = requirements.requiredSkills.split(',');
const candidateSkills = candidateData.skills || [];
const skillsMatch = requiredSkills.filter(skill => 
  candidateSkills.some(cSkill => cSkill.toLowerCase().includes(skill.toLowerCase()))
);
const skillsScore = (skillsMatch.length / requiredSkills.length) * 40;
totalScore += skillsScore;

// Experience scoring (30% weight)
const experienceYears = candidateData.experience_years || 0;
let experienceScore = 0;
if (experienceYears >= requirements.minExperience) {
  experienceScore = 30;
} else if (experienceYears >= requirements.minExperience * 0.8) {
  experienceScore = 25;
} else if (experienceYears >= requirements.minExperience * 0.6) {
  experienceScore = 20;
} else {
  experienceScore = 10;
}
totalScore += experienceScore;

// Education scoring (20% weight)
const education = candidateData.education || '';
let educationScore = 0;
if (education.toLowerCase().includes('master') || education.toLowerCase().includes('phd')) {
  educationScore = 20;
} else if (education.toLowerCase().includes('bachelor') || education.toLowerCase().includes('degree')) {
  educationScore = 15;
} else {
  educationScore = 10;
}
totalScore += educationScore;

// Role relevance (10% weight)
const previousRoles = candidateData.previous_roles || [];
const roleRelevance = previousRoles.some(role => 
  role.toLowerCase().includes('engineer') || role.toLowerCase().includes('developer')
) ? 10 : 5;
totalScore += roleRelevance;

// Determine recommendation
let recommendation = 'reject';
let priority = 'low';

if (totalScore >= 85) {
  recommendation = 'hire';
  priority = 'high';
} else if (totalScore >= requirements.passingScore) {
  recommendation = 'interview';
  priority = 'medium';
} else if (totalScore >= 60) {
  recommendation = 'phone_screen';
  priority = 'low';
}

return {
  candidateData,
  scoring: {
    skillsScore,
    experienceScore,
    educationScore,
    roleRelevance,
    totalScore: Math.round(totalScore),
    recommendation,
    priority
  },
  jobTitle: requirements.jobTitle,
  evaluatedAt: new Date().toISOString()
};"},"typeVersion":1},{"id":"6","name":"Check If Top Candidate","type":"n8n-nodes-base.if","position":[1040,200],"parameters":{"conditions":{"options":{"leftValue":"","caseSensitive":true,"typeValidation":"strict"},"conditions":[{"operator":{"type":"string","operation":"equals"},"leftValue":"={{ $json.scoring.recommendation }}","rightValue":"hire"}]}},"typeVersion":2},{"id":"7","name":"Alert HR Team","type":"n8n-nodes-base.gmail","position":[1240,100],"parameters":{"sendTo":"={{ $node['Job Requirements'].json.hrEmail }}","message":"=<!DOCTYPE html>
<html>
