const root = $json.body ?? $json;   // ← marche avec ou sans "body"

// ─── 1. Cherche l'objet "message", quel que soit le chemin ─────────────
let msg;

if (root.message) {
  // cas où un Set/Split l’a déjà extrait
  msg = root.message;
} else if (root.entry?.[0]?.messaging?.[0]?.message) {
  // structure brute Facebook
  msg = root.entry[0].messaging[0].message;
} else {
  throw new Error('Impossible de localiser le champ "message"');
}

// ─── 2. Prépare la sortie standardisée ─────────────────────────────────
let result;

if (msg.attachments?.[0]) {
  const att = msg.attachments[0];
  if (att.type === 'image') {
    result = { type: 'image', url: att.payload?.url };
  } else if (att.type === 'audio') {
    result = { type: 'audio', url: att.payload?.url };
  } else {
    result = { type: att.type || 'attachment', url: att.payload?.url };
  }
} else if (msg.text) {
  result = { type: 'text', text: msg.text };
} else {
  result = { type: 'unknown' };
}

// ─── 3. Retourne l'objet pour les nœuds suivants ───────────────────────
return [ result ];"},"typeVersion":1},{"id":"4c783fcc-48ab-4381-ba12-d730d7837c30","name":"Edit Fields1","type":"n8n-nodes-base.set","position":[1248,784],"parameters":{"options":{},"assignments":{"assignments":[{"id":"5a5d4ec5-61d5-471c-bab7-135528008e6c","name":"user_prompt","type":"string","value":"={{ $json.text }}"}]},"includeOtherFields":true},"typeVersion":3.4},{"id":"752e4920-7677-4e78-bef9-1ee55478b33a","name":"Edit Fields2","type":"n8n-nodes-base.set","position":[1632,448],"parameters":{"options":{},"assignments":{"assignments":[{"id":"5a5d4ec5-61d5-471c-bab7-135528008e6c","name":"user_prompt","type":"string","value":"={{ $json.text }}"}]},"includeOtherFields":true},"typeVersion":3.4},{"id":"391e29fb-4b60-407e-a1f1-db0740fddf14","name":"Edit Fields3","type":"n8n-nodes-base.set","position":[1632,112],"parameters":{"options":{},"assignments":{"assignments":[{"id":"5a5d4ec5-61d5-471c-bab7-135528008e6c","name":"user_prompt","type":"string","value":"={{ $json.content }}"}]},"includeOtherFields":true},"typeVersion":3.4},{"id":"66394ce4-5a3d-45a8-8929-a5fe5d8399be","name":"Code1","type":"n8n-nodes-base.code","position":[3152,448],"parameters":{"jsCode":"// -------- Build Messenger Payload ----------
