{"nodes":[{"id":"15341b2a-14b2-4341-8b18-8cd1fc5c79f1","name":"Schedule Trigger","type":"n8n-nodes-base.scheduleTrigger","position":[-400,144],"parameters":{"rule":{"interval":[{}]}},"typeVersion":1.2},{"id":"639b483f-1347-4361-990a-499d7a985398","name":"Search Lead Source","type":"n8n-nodes-base.airtable","position":[176,144],"parameters":{"base":{"__rl":true,"mode":"list","value":"appeCsmVosYvWkVM3","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3","cachedResultName":"Contacts"},"table":{"__rl":true,"mode":"list","value":"tblPecJqyJn6lmSDj","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3/tblPecJqyJn6lmSDj","cachedResultName":"Lead Sources"},"options":{},"operation":"search"},"credentials":{"airtableTokenApi":{"id":"ifs1pAy5yAfPBZtY","name":"Airtable Personal Access Token account"}},"typeVersion":2.1},{"id":"d2904611-761a-4c85-8445-b2f60caf5672","name":"Code in JavaScript","type":"n8n-nodes-base.code","position":[400,144],"parameters":{"jsCode":"// @ts-nocheck

// Access data from specific nodes by their names
const dealsData = $('Deals').all();
const leadSourcesData = $('Search Lead Source').all();

// Create a map for lead sources
const sourceMap = new Map();

leadSourcesData.forEach((item) => {
  const fields = item.json.fields || item.json;
  const sourceName = fields['Source Name'] || fields['Lead Source'];

  sourceMap.set(sourceName, {
    sourceType: fields['Source Type'],
    cost: parseFloat(fields['Cost per Lead']) || 0,
    totalLeads: parseInt(fields['Total Leads Generated']) || 0
  });
});

const sourceRevenue = new Map();

dealsData.forEach((item) => {
  const fields = item.json.fields || item.json;
  const source = fields['Deal Source'] || fields['Lead Source'];
  const revenue = parseFloat(fields['Deal Value']) || 0;

  if (!sourceRevenue.has(source)) {
    sourceRevenue.set(source, {
      totalRevenue: 0,
      dealCount: 0,
      source: source
    });
  }

  const current = sourceRevenue.get(source);
  current.totalRevenue += revenue;
  current.dealCount += 1;
});

// Calculate ROI for each source
/** @type {any[]} */
const results = [];

sourceRevenue.forEach((data, sourceName) => {
  const sourceInfo = sourceMap.get(sourceName) || { cost: 0, totalLeads: 0 };

  const totalCost = sourceInfo.cost * sourceInfo.totalLeads;
  const roi = totalCost > 0 ? ((data.totalRevenue - totalCost) / totalCost) * 100 : 0;
  const avgDealSize = data.dealCount > 0 ? data.totalRevenue / data.dealCount : 0;
  const conversionRate = sourceInfo.totalLeads > 0 ? (data.dealCount / sourceInfo.totalLeads) * 100 : 0;

  results.push({
    json: {
      source: sourceName,
      totalRevenue: data.totalRevenue,
      dealCount: data.dealCount,
      avgDealSize: avgDealSize,
      totalCost: totalCost,
      roi: parseFloat(roi.toFixed(2)),
      conversionRate: parseFloat(conversionRate.toFixed(2)),
      updated_at: new Date().toISOString()
    }
  });
});

// Sort by ROI descending
results.sort((a, b) => b.json.roi - a.json.roi);

return results;"},"typeVersion":2},{"id":"0542491a-d85d-4431-8ac0-fa8278a58088","name":"Deals","type":"n8n-nodes-base.airtable","position":[-80,144],"parameters":{"base":{"__rl":true,"mode":"list","value":"appeCsmVosYvWkVM3","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3","cachedResultName":"Contacts"},"table":{"__rl":true,"mode":"list","value":"tblJlUYIVVJrYrUZl","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3/tblJlUYIVVJrYrUZl","cachedResultName":"Deals"},"options":{},"operation":"search","filterByFormula":"=AND({Stage} = "Closed Won", IS_AFTER({Actual Close Date}, DATEADD(NOW(), -30, 'days')))"},"credentials":{"airtableTokenApi":{"id":"ifs1pAy5yAfPBZtY","name":"Airtable Personal Access Token account"}},"typeVersion":2.1},{"id":"e92d2b3c-16ac-4979-8368-4208b533bab0","name":"Loop Over Items","type":"n8n-nodes-base.splitInBatches","position":[624,144],"parameters":{"options":{}},"typeVersion":3},{"id":"fbe7af8c-9d26-4f68-a78b-f35ece1c958e","name":"Search records","type":"n8n-nodes-base.airtable","position":[832,160],"parameters":{"base":{"__rl":true,"mode":"list","value":"appeCsmVosYvWkVM3","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3","cachedResultName":"Contacts"},"table":{"__rl":true,"mode":"list","value":"tblPecJqyJn6lmSDj","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3/tblPecJqyJn6lmSDj","cachedResultName":"Lead Sources"},"options":{},"operation":"search","filterByFormula":"={Source Type} = "{{ $json.source }}""},"credentials":{"airtableTokenApi":{"id":"ifs1pAy5yAfPBZtY","name":"Airtable Personal Access Token account"}},"typeVersion":2.1},{"id":"85233782-5af1-44e7-80e6-4385c5c0f279","name":"Update record","type":"n8n-nodes-base.airtable","position":[1040,160],"parameters":{"base":{"__rl":true,"mode":"list","value":"appeCsmVosYvWkVM3","cachedResultUrl":"https://airtable.com/appeCsmVosYvWkVM3","cachedResultName":"Contacts"},"table":{"__rl":true,"mode":"list","value":"YOUR_AIRTABLE_VALUE","cachedResultUrl":"https://airt